mapper.select:
select 


order by ea.sort_order, ea.area_code, ei.sort_order, ei.item_code, ee.evaluation_year desc, ee.sort_order, ee.element_code, aess.target_scope
limit #{criteria.safeSize} offset #{criteria.offset}

select version_status
from evaluation_rule_versions
where rule_version_id = #{ruleVersionId}

select ea.area_id as "areaId",
       ei.item_id as "itemId",
       ee.element_id as "elementId"
from evaluation_elements ee
inner join evaluation_items ei on ei.item_id = ee.item_id
inner join evaluation_areas ea on ea.area_id = ei.area_id
where ea.rule_version_id = #{ruleVersionId}
  and ea.area_code = #{areaCode}
  and ei.item_code = #{itemCode}
  and ee.evaluation_year = #{evaluationYear}
  and ee.element_code = #{elementCode}

select 

where aess.area_id = #{areaId}
  and aess.item_id = #{itemId}
  and aess.element_id = #{elementId}
  and aess.target_scope = #{targetScope}
